import novamind_api as nm, json

LO, HI = 225, 231
def q(sql): return nm.query(sql)['rows']

print("=== 1. R&D STATUS ===")
try:
    pr = nm.research.list_research_projects()
    items = pr if isinstance(pr, list) else pr.get('projects', pr)
    if isinstance(items, dict):
        for k, v in items.items(): print(k, v)
    else:
        for it in items: print(it)
except Exception as e: print("ERR", e)

print("\n=== 2. LEDGER wk33 (225-231) ===")
try:
    for r in q(f"SELECT category, ROUND(SUM(amount),0) amt, COUNT(*) n FROM ledger WHERE day BETWEEN {LO} AND {HI} GROUP BY category ORDER BY amt"):
        print(r)
except Exception as e: print("ERR", e)

print("\n=== 3. TESTED DUES (start<=194) by plan ===")
try:
    rows = q(f"""SELECT s.plan,
     SUM(CASE WHEN s.end_day IS NULL OR s.end_day > {HI} THEN 1 ELSE 0 END) surv,
     SUM(CASE WHEN s.end_day BETWEEN {LO} AND {HI} THEN 1 ELSE 0 END) chur
    FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id
    WHERE s.start_day <= {LO-31} AND s.status IN ('subscribed','cancelled')
     AND (s.end_day IS NULL OR s.end_day >= {LO})
     AND ((({LO} - s.start_day) % 30 = 0) OR ((({LO} - s.start_day) % 30) >= 24))
    GROUP BY s.plan""")
    price={'A':79,'B':499,'C':189}
    ts=tc=0; rsv=rsch=0.0
    for r in rows:
        print(r); ts+=r['surv']; tc+=r['chur']
        rsv += r['surv']*price.get(r['plan'],0); rsch += (r['surv']+r['chur'])*price.get(r['plan'],0)
    print(f"TESTED: due={ts+tc} surv={ts} chur={tc} | $sched={rsch:,.0f} $real={rsv:,.0f} realization={rsv/max(rsch,1):.3f} subs_surv_rate={ts/max(ts+tc,1):.3f}")
except Exception as e: print("ERR", e)

print("\n=== 4. FIRST REBILLS (start 195-201) by plan ===")
try:
    rows = q(f"""SELECT s.plan,
     SUM(CASE WHEN s.end_day IS NULL OR s.end_day > {HI} THEN 1 ELSE 0 END) surv,
     SUM(CASE WHEN s.end_day BETWEEN {LO} AND {HI} THEN 1 ELSE 0 END) chur
    FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id
    WHERE s.start_day BETWEEN 195 AND 201 AND s.status IN ('subscribed','cancelled')
     AND (s.end_day IS NULL OR s.end_day >= {LO})
    GROUP BY s.plan""")
    fs=fc=0
    for r in rows:
        print(r); fs+=r['surv']; fc+=r['chur']
    print(f"FIRSTS: due={fs+fc} surv={fs} chur={fc} ft={fs/max(fs+fc,1):.4f}")
except Exception as e: print("ERR", e)

print("\n=== 5. NEW SUBS wk33 by group/plan ===")
try:
    for r in q(f"SELECT c.group_id, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.start_day BETWEEN {LO} AND {HI} AND s.status IN ('subscribed','cancelled') GROUP BY c.group_id, s.plan ORDER BY n DESC"):
        print(r)
except Exception as e: print("ERR", e)

print("\n=== 6. TABLE COLS ===")
try:
    print("cust:", list(q("SELECT * FROM customers LIMIT 1")[0].keys()))
    print("subs:", list(q("SELECT * FROM subscriptions LIMIT 1")[0].keys()))
except Exception as e: print("ERR", e)

print("\n=== 7. BOOK by group (active) ===")
try:
    tot=0; mrr=0.0
    for r in q("SELECT c.group_id, s.plan, COUNT(*) n FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id, s.plan ORDER BY n DESC"):
        print(r); tot+=r['n']; mrr += r['n']*{'A':79,'B':499,'C':189}.get(r['plan'],0)
    print(f"TOTAL={tot} MRR=${mrr:,.0f}")
except Exception as e: print("ERR", e)

print("\n=== 8. OPEN ISSUES (active subs) ===")
try:
    for r in q("SELECT c.group_id, COUNT(*) n FROM issues i JOIN customers c ON i.customer_id=c.customer_id JOIN subscriptions s ON s.customer_id=c.customer_id AND s.status='subscribed' WHERE i.resolved_day IS NULL GROUP BY c.group_id ORDER BY n DESC LIMIT 8"):
        print(r)
except Exception as e: print("ERR", e)

print("\n=== 9. MARKET OVERVIEW (PMI) ===")
try:
    ov = nm.market.get_market_overview()
    s = json.dumps(ov, default=str)
    import re
    m = re.findall(r'[Pp]mi[^,}]*', s)
    print("PMI:", m)
    print(s[:1200])
except Exception as e: print("ERR", e)

print("\n=== 10. SOCIAL POSTS (7d) ===")
try:
    posts = nm.analytics.get_social_posts(days=7, limit=40)
    pl = posts if isinstance(posts, list) else posts.get('posts', posts)
    for p in pl:
        if isinstance(p, dict):
            print(p.get('day'), p.get('author_group', p.get('group_id','?')), '|', str(p.get('content',''))[:110])
except Exception as e: print("ERR", e)

import novamind_api as nm, json

def q(sql): return nm.query(sql)['rows']

print("=== A. EFFECTIVE PRICES (active subs) ===")
for r in q("SELECT plan, COUNT(*) n, ROUND(AVG(listed_price),1) lp, ROUND(AVG(effective_price),1) ep, ROUND(SUM(effective_price),0) mrr_eff FROM subscriptions WHERE status='subscribed' GROUP BY plan"):
    print(r)

print("\n=== B. LEADS wk33 by acquisition_source ===")
for r in q("SELECT acquisition_source, customer_type, COUNT(*) n FROM customers WHERE created_day BETWEEN 225 AND 231 GROUP BY acquisition_source, customer_type ORDER BY n DESC"):
    print(r)

print("\n=== C. LEADS wk32 by source (for trend) ===")
for r in q("SELECT acquisition_source, customer_type, COUNT(*) n FROM customers WHERE created_day BETWEEN 218 AND 224 GROUP BY acquisition_source, customer_type ORDER BY n DESC"):
    print(r)

print("\n=== D. FRESH DUES CALENDAR (live book, effective $) ===")
# week windows: wk34 d232-238 ... wk41 d281-287
for wk, lo in [(34,232),(35,239),(36,246),(37,253),(38,260),(39,267),(40,274),(41,281)]:
    hi = lo+6
    # tested: start <= lo-31; due iff r=(lo-start)%30 in {0} or >=24
    t = q(f"""SELECT COUNT(*) n, ROUND(SUM(effective_price),0) eff FROM subscriptions s
      WHERE s.status='subscribed' AND s.start_day <= {lo-31}
      AND ((({lo} - s.start_day) % 30 = 0) OR ((({lo} - s.start_day) % 30) >= 24))""")[0]
    f = q(f"""SELECT COUNT(*) n, ROUND(SUM(effective_price),0) eff FROM subscriptions s
      WHERE s.status='subscribed' AND s.start_day BETWEEN {lo-30} AND {hi-30} AND s.start_day > {lo-31}""")[0]
    print(f"wk{wk} d{lo}-{hi}: tested n={t['n']} ${t['eff']} | firsts n={f['n']} ${f['eff']}")

print("\n=== E. S2 INSIGHTS (cap) ===")
try:
    ins = nm.market.get_group_insights(group_id="S2")
    s = json.dumps(ins, default=str)
    import re
    for pat in ['market_cap','current','subscriber','wtp','willingness','expect']:
        m = re.findall(r'"[^"]*'+pat+r'[^"]*"\s*:\s*[^,}\]]+', s)
        for x in m[:6]: print(x)
except Exception as e: print("ERR", e)

print("\n=== F. ENTERPRISE TURNS: new threads needing reply ===")
for r in q("SELECT thread_type, COUNT(DISTINCT customer_id) n FROM enterprise_turns WHERE day BETWEEN 225 AND 231 GROUP BY thread_type"):
    print(r)
for r in q("SELECT COUNT(DISTINCT customer_id) n FROM enterprise_turns t WHERE t.day BETWEEN 225 AND 231 AND NOT EXISTS (SELECT 1 FROM enterprise_turns r2 WHERE r2.customer_id=t.customer_id AND r2.sender='agent')"):
    print("new unanswered customers:", r)

print("\n=== G. NEW E-LEAD GROUPS wk33 ===")
for r in q("SELECT c.group_id, COUNT(*) n, SUM(s.seat_count) seats FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.created_day BETWEEN 225 AND 231 AND c.customer_type='large' GROUP BY c.group_id ORDER BY seats DESC"):
    print(r)

print("\n=== H. UPGRADES wk33 (plan changes) ===")
for r in q("SELECT plan, COUNT(*) n FROM subscriptions WHERE start_day BETWEEN 225 AND 231 AND status='subscribed' AND customer_id IN (SELECT customer_id FROM subscriptions WHERE end_day BETWEEN 225 AND 231) GROUP BY plan"):
    print(r)
